export const taskList = [
    { id: 1, name: '任务1',  startAddress: '起点1', endAddress: '终点1', startPointLng: 104.065735, endPointLng: 114.065735, startPointLat: 30.659462, endPointLat: 31.659462 },
    { id: 2, name: '任务2', startAddress: '起点2', endAddress: '终点2', startPointLng: 104.066735, endPointLng: 114.066735, startPointLat: 30.660462, endPointLat: 31.660462 },
    { id: 3, name: '任务3', startAddress: '起点3', endAddress: '终点3', startPointLng: 104.067735, endPointLng: 114.067735, startPointLat: 30.661462, endPointLat: 31.661462 },
]


const generate = () => {
    return   taskList.map((item, index) => {
        return {
            id: item.id,
            name: item.name,
            startAddress: item.startAddress,
            endAddress: item.endAddress,
            startPoint: item.startPointLng+','+item.startPointLat,
            endPoint: item.endPointLng+','+item.endPointLat ,
            startTime: new Date().toISOString(),
            endTime: new Date().toISOString(),
            type: 'type' + (index % 3),
            amount: Math.floor(Math.random() * 1000),
            unit: '件',
            freight: Math.floor(Math.random() * 500),
            status: index % 2 === 0 ? '进行中' : '已完成'
        };
    })
}

export const paginate = <T>({ list, page, pageSize }: {list: T[], page: number, pageSize: number}): { data: T[], total: number } => {
    let lists = generate()
    const total = lists.length;
   // const count = Math.ceil(total / pageSize); // 总页数

    // 计算起始索引和结束索引
    const start = (page - 1) * pageSize;
    const end = start + pageSize;

    const data = lists.slice(start, end); // 当前页数据

    return {
        data,
        total
    };
};
